begin;create extension if not exists pgtap with schema extensions;select plan(17);insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99700000-0000-4000-8000-000000000001','authenticated','authenticated','delivery-owner@example.test','',now(),'{"display_name":"Driver Ben"}',now(),now());set local role authenticated;select set_config('request.jwt.claim.sub','99700000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99700000-0000-4000-8000-000000000001","role":"authenticated"}',true);select public.create_business('delivery-test','Delivery Test','Delivery Test','sole_proprietorship','retail','{}');select set_config('test.del_org',(select id::text from public.organizations where slug='delivery-test'),true);select set_config('test.del_branch',(select id::text from public.branches where organization_id=current_setting('test.del_org')::uuid),true);select is(public.can_business_permission(current_setting('test.del_org')::uuid,'delivery.manage'),true,'Owner receives delivery permission');reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.del_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','99700000-0000-4000-8000-000000000001',true);select public.set_business_module_state(current_setting('test.del_org')::uuid,'sales',true,'{}');select set_config('test.del_customer',public.save_sales_customer(current_setting('test.del_org')::uuid,null,'Maria Santos','09171234567','')::text,true);
select throws_ok($$select public.save_delivery(current_setting('test.del_org')::uuid,current_setting('test.del_branch')::uuid,current_setting('test.del_customer')::uuid,'Makati','0917',null,now()+interval'1 day','','internal')$$,'42501','Permission denied.','Disabled delivery module rejects writes');select lives_ok($$select public.set_business_module_state(current_setting('test.del_org')::uuid,'delivery',true,'{"require_proof_of_delivery":true,"default_courier_provider":"internal"}')$$,'Delivery activates with Sales dependency');select results_eq($$select display_name,status from public.delivery_drivers where organization_id=current_setting('test.del_org')::uuid$$,$$select 'Driver Ben'::text,'active'::text$$,'Active members become assignable drivers');select set_config('test.del_driver',(select id::text from public.delivery_drivers where organization_id=current_setting('test.del_org')::uuid),true);
select set_config('test.del1',public.save_delivery(current_setting('test.del_org')::uuid,current_setting('test.del_branch')::uuid,current_setting('test.del_customer')::uuid,'123 Ayala Avenue, Makati','09171234567',null,now()+interval'1 day','Van ABC-123','internal')::text,true);select results_eq($$select delivery_number,status,delivery_address,contact_number,courier_provider from public.deliveries where id=current_setting('test.del1')::uuid$$,$$select 'DEL-'||extract(year from current_date)::integer||'-000001','pending'::text,'123 Ayala Avenue, Makati'::text,'09171234567'::text,'internal'::text$$,'Delivery stores requested details and stable provider key');
select lives_ok($$select public.change_delivery_status(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,'scheduled','Scheduled')$$,'Pending delivery can be scheduled');select lives_ok($$select public.assign_delivery_driver(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,current_setting('test.del_driver')::uuid,'Van ABC-123')$$,'Scheduled delivery can receive a driver');select results_eq($$select status,assigned_driver_id from public.deliveries where id=current_setting('test.del1')::uuid$$,$$select 'assigned'::text,current_setting('test.del_driver')::uuid$$,'Assignment advances the delivery lifecycle');select lives_ok($$select public.change_delivery_status(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,'out_for_delivery','Departed')$$,'Assigned delivery can depart');select throws_ok($$select public.change_delivery_status(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,'delivered','Received')$$,'P0001','Invalid delivery status transition.','Configured proof is required before completion');
select lives_ok($$select public.attach_delivery_proof(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,current_setting('test.del_org')||'/'||current_setting('test.del1')||'/proof.jpg','proof.jpg','image/jpeg',1024,'Signed by customer')$$,'Proof metadata can be attached');select lives_ok($$select public.change_delivery_status(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,'delivered','Received by Maria')$$,'Proof-backed delivery can complete');select results_eq($$select status,(delivered_at is not null)from public.deliveries where id=current_setting('test.del1')::uuid$$,$$select 'delivered'::text,true$$,'Delivered state records completion time');select results_eq($$select count(*)from public.delivery_status_history where delivery_id=current_setting('test.del1')::uuid$$,$$select 5::bigint$$,'Creation and every lifecycle change remain in delivery history');select throws_ok($$select public.change_delivery_status(current_setting('test.del_org')::uuid,current_setting('test.del1')::uuid,'cancelled','Undo')$$,'P0001','Invalid delivery status transition.','Delivered records are terminal');select throws_ok($$update public.delivery_status_history set to_status='cancelled'where delivery_id=current_setting('test.del1')::uuid$$,'42501','permission denied for table delivery_status_history','Clients cannot rewrite delivery history');select results_eq($$select count(*)from public.role_permissions assignment join public.roles role on role.id=assignment.role_id join public.permissions permission on permission.id=assignment.permission_id where role.organization_id=current_setting('test.del_org')::uuid and role.key='manager'and permission.key like'delivery.%'$$,$$select 5::bigint$$,'Managers receive every delivery permission');select*from finish();rollback;
